CREATE SCHEMA IF NOT EXISTS balwyn_portal;

REVOKE ALL ON SCHEMA balwyn_portal FROM PUBLIC, anon, authenticated;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'balwyn_app') THEN CREATE ROLE balwyn_app NOLOGIN; END IF; END $$;

GRANT USAGE ON SCHEMA balwyn_portal TO balwyn_app;

CREATE TABLE balwyn_portal.activity_log (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "action" text NOT NULL,
  "detail" text NOT NULL,
  "category" text NOT NULL,
  "actor_name" text NOT NULL,
  "actor_role" text NOT NULL,
  "created_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);

ALTER TABLE balwyn_portal.activity_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.activity_log TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.auth_attempts (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "fingerprint" text NOT NULL,
  "success" integer NOT NULL,
  "created_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);

ALTER TABLE balwyn_portal.auth_attempts ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.auth_attempts TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.automation_rules (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" text NOT NULL,
  "trigger" text NOT NULL,
  "action" text NOT NULL,
  "enabled" integer NOT NULL DEFAULT 1,
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "updated_by" text NOT NULL DEFAULT 'system'
);

ALTER TABLE balwyn_portal.automation_rules ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.automation_rules TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.command_queue (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "correlation_id" text NOT NULL,
  "gate_id" text NOT NULL,
  "command" text NOT NULL,
  "state" text NOT NULL DEFAULT 'queued',
  "requested_by" text NOT NULL,
  "requested_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "expires_at" text NOT NULL,
  "dispatched_at" text,
  "acknowledged_at" text,
  "detail" text,
  "source" text NOT NULL DEFAULT 'manual'
);

ALTER TABLE balwyn_portal.command_queue ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.command_queue TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.gate_states (
  "gate_id" text PRIMARY KEY NOT NULL,
  "commanded_position" text NOT NULL DEFAULT 'closed',
  "reported_position" text NOT NULL DEFAULT 'unknown',
  "controller_state" text NOT NULL DEFAULT 'uncommissioned',
  "commissioned" integer NOT NULL DEFAULT 0,
  "safety_ok" integer,
  "controller_token_hash" text,
  "last_seen" text,
  "last_command_id" integer,
  "last_command_state" text NOT NULL DEFAULT 'idle',
  "last_error" text,
  "software_version" text,
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);

ALTER TABLE balwyn_portal.gate_states ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.gate_states TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.portal_settings (
  "id" integer PRIMARY KEY NOT NULL,
  "position_monitoring" integer NOT NULL DEFAULT 1,
  "fault_alerts" integer NOT NULL DEFAULT 1,
  "voice_announcements" integer NOT NULL DEFAULT 1,
  "enabled_modules" text NOT NULL DEFAULT '["mobile"]',
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "updated_by" text NOT NULL DEFAULT 'system',
  "equipment" text
);

ALTER TABLE balwyn_portal.portal_settings ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.portal_settings TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.gate_schedules (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "gate_id" text NOT NULL,
  "day" text NOT NULL,
  "enabled" integer NOT NULL DEFAULT 0,
  "open_time" text NOT NULL,
  "close_time" text NOT NULL,
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "updated_by" text NOT NULL DEFAULT 'system'
);

ALTER TABLE balwyn_portal.gate_schedules ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.gate_schedules TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.system_state (
  "id" integer PRIMARY KEY NOT NULL,
  "mode" text NOT NULL DEFAULT 'normal',
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "updated_by" text NOT NULL DEFAULT 'system'
);

ALTER TABLE balwyn_portal.system_state ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.system_state TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.operator_totp (
  "username" text PRIMARY KEY NOT NULL,
  "encrypted_secret" text NOT NULL,
  "enrolled_at" text,
  "last_used_counter" integer NOT NULL DEFAULT -1,
  "created_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);

ALTER TABLE balwyn_portal.operator_totp ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.operator_totp TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.google_login_challenges (
  "state_hash" text PRIMARY KEY NOT NULL,
  "browser_hash" text NOT NULL,
  "nonce" text NOT NULL,
  "expires_at" bigint NOT NULL
);

ALTER TABLE balwyn_portal.google_login_challenges ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.google_login_challenges TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.microsoft_login_challenges (
  "state_hash" text PRIMARY KEY NOT NULL,
  "browser_hash" text NOT NULL,
  "nonce" text NOT NULL,
  "verifier" text NOT NULL,
  "expires_at" bigint NOT NULL
);

ALTER TABLE balwyn_portal.microsoft_login_challenges ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.microsoft_login_challenges TO balwyn_app USING (true) WITH CHECK (true);

CREATE TABLE balwyn_portal.user_profiles (
  "id" text PRIMARY KEY NOT NULL,
  "account_key" text NOT NULL,
  "display_name" text NOT NULL,
  "username" text,
  "contact_email" text NOT NULL DEFAULT '',
  "phone" text NOT NULL DEFAULT '',
  "job_title" text NOT NULL DEFAULT '',
  "avatar_key" text,
  "updated_at" text NOT NULL DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);

ALTER TABLE balwyn_portal.user_profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY balwyn_server_access ON balwyn_portal.user_profiles TO balwyn_app USING (true) WITH CHECK (true);

CREATE INDEX "idx_activity_log_created_at" ON balwyn_portal.activity_log ("created_at");

CREATE INDEX "idx_auth_attempts_fingerprint_time" ON balwyn_portal.auth_attempts ("fingerprint","created_at");

CREATE UNIQUE INDEX "idx_command_queue_correlation_gate" ON balwyn_portal.command_queue ("correlation_id","gate_id");

CREATE INDEX "idx_command_queue_gate_state" ON balwyn_portal.command_queue ("gate_id","state");

CREATE UNIQUE INDEX "idx_gate_schedules_gate_day" ON balwyn_portal.gate_schedules ("gate_id","day");

CREATE UNIQUE INDEX "idx_automation_rules_name" ON balwyn_portal.automation_rules ("name");

CREATE INDEX "idx_google_login_challenges_expiry" ON balwyn_portal.google_login_challenges ("expires_at");

CREATE INDEX "idx_microsoft_login_challenges_expiry" ON balwyn_portal.microsoft_login_challenges ("expires_at");

CREATE UNIQUE INDEX "idx_user_profiles_account" ON balwyn_portal.user_profiles ("account_key");

CREATE UNIQUE INDEX "idx_user_profiles_username" ON balwyn_portal.user_profiles ("username");

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA balwyn_portal TO balwyn_app;

GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA balwyn_portal TO balwyn_app;

GRANT balwyn_app TO postgres;

INSERT INTO storage.buckets (id,name,public,file_size_limit,allowed_mime_types) VALUES ('balwyn-profile-photos','balwyn-profile-photos',false,3145728,ARRAY['image/png','image/jpeg','image/webp']) ON CONFLICT(id) DO NOTHING;
